function przejdzDoZakladki(nazwa) {
  const stan = { zakladka: nazwa, czas: Date.now() };
  const url = `?zakladka=${nazwa}`;

  history.pushState(stan, "", url);
  console.log("Nowy URL:", location.href); // zmieniony, bez przeladowania
}

przejdzDoZakladki("produkty");
// -> "Nowy URL: .../strona?zakladka=produkty"

window.addEventListener("popstate", (e) => {
  const zakladka = e.state?.zakladka ?? "domyslna";
  console.log("Powrot do zakladki:", zakladka);
  // tutaj: ponowne wyrenderowanie odpowiedniej tresci na podstawie e.state
});

function renderZakladka(zakladka) {
  const tresci = {
    home: "Zawartosc: Home",
    produkty: "Zawartosc: Produkty",
    onas: "Zawartosc: O nas",
  };
  document.getElementById("tab-content").textContent =
    tresci[zakladka] ?? "Nieznana zakladka";
}

function przejdzDoZakladki(zakladka) {
  history.pushState({ zakladka }, "", `?zakladka=${zakladka}`);
  renderZakladka(zakladka); // renderuj OD RAZU, bo pushState tego nie robi
}

window.addEventListener("popstate", (e) => {
  renderZakladka(e.state?.zakladka ?? "home"); // ta sama funkcja renderujaca
});

function zleNawiguj(zakladka) {
  history.pushState({ zakladka }, "", `?zakladka=${zakladka}`);
  // BRAK wywolania funkcji renderujacej - DOM pozostaje bez zmian!
}

function dobrzeNawiguj(zakladka) {
  history.pushState({ zakladka }, "", `?zakladka=${zakladka}`);
  renderZakladka(zakladka); // DOBRZE - reczna aktualizacja DOM
}

