console.log(location.href); // zawiera "?krok=2"

window.addEventListener("popstate", (e) => {
  console.log(e.state ?? "brak stanu");
});

function renderKrok(numer) {
  console.log(`Renderuje krok: ${numer}`);
}

function przejdzDoKrokuZRenderowaniem(numer) {
  history.pushState({ krok: numer }, "", `?krok=${numer}`);
  renderKrok(numer);
}

przejdzDoKrokuZRenderowaniem(3); // "Renderuje krok: 3"

window.addEventListener("popstate", (e) => {
  renderKrok(e.state?.krok ?? 1);
});

history.replaceState({ poprawiono: true }, "", "?wersja=2");
// W odroznieniu od pushState, replaceState NIE dodaje nowego wpisu do
// historii nawigacji - zastepuje AKTUALNY wpis. Przycisk 'Wstecz'
// pominie ten krok, jakby go wcale nie bylo - dobre do 'cichych'
// korekt URL, ktore nie powinny tworzyc osobnego kroku nawigacji.

document.getElementById("btn-wstecz").addEventListener("click", () => {
