class MockHistory {
  constructor() {
    this._wpisy = ["/a", "/b", "/c"];
    this._pozycja = 2;
  }
  back() { this.go(-1); }
  forward() { this.go(1); }
  go(delta) {
    const nowa = this._pozycja + delta;
    if (nowa >= 0 && nowa < this._wpisy.length) this._pozycja = nowa;
  }
}
const history = new MockHistory();
history.back();
