class MockHistory {
  constructor() { this._wpisy = []; }
  pushState(stan, tytul, url) { this._wpisy.push({ stan, url }); }
}
function cofnijDoKroku(history, docelowyKrok) {
  while (history._wpisy.length > 0 && history._wpisy[history._wpisy.length - 1].stan.krok !== docelowyKrok) {
    history._wpisy.pop();
  }
