function policzWpisyZeStanem(history, klucz) {
  return history._wpisy.filter((w) => w.stan && Object.prototype.hasOwnProperty.call(w.stan, klucz)).length;
}
const history = {
  _wpisy: [
    { stan: { krok: 1 } },
    { stan: null },
    { stan: { krok: 2 } },
  ],
};
