// Biblioteki routingu (np. react-router) NIE wymyslaja wlasnego
// mechanizmu zmiany URL bez przeladowania strony - korzystaja z
// DOKLADNIE tych samych, wbudowanych mechanizmow przegladarki co
// wlasnorecznie napisany kod: history.pushState przy nawigacji miedzy
// "podstronami" aplikacji oraz nasluchiwanie zdarzenia popstate przy
// przyciskach Wstecz/Naprzod przegladarki. To, co dodaja biblioteki, to
// wygodna warstwa abstrakcji (deklaratywne komponenty <Route>,
// dopasowywanie wzorcow sciezek, zagniezdzone trasy) zbudowana NAD tymi
// samymi, podstawowymi mechanizmami History API.
console.log("react-router opiera sie na pushState/popstate pod spodem");

class MockHistory {
  constructor() { this._wpisy = []; }
  pushState(stan, tytul, url) { this._wpisy.push({ stan, url }); }
}
function przejdzWarunkowo(history, sciezka, warunek) {
  if (!warunek()) return "zablokowano";
  history.pushState(null, "", sciezka);
  return "przeszlo";
}
const history = new MockHistory();
console.log(przejdzWarunkowo(history, "/krok2", () => false));
console.log(przejdzWarunkowo(history, "/krok2", () => true));
// "zablokowano"
// "przeszlo"

function ostatniaSciezka(history) {
  if (history._wpisy.length === 0) return "/";
  return history._wpisy[history._wpisy.length - 1].url;
}
const historiaPusta = { _wpisy: [] };
const historiaZWpisami = { _wpisy: [{ url: "/a" }, { url: "/b" }] };
console.log(ostatniaSciezka(historiaPusta));
console.log(ostatniaSciezka(historiaZWpisami));
// "/"
// "/b"

function sumaKrokow(history) {
  return history._wpisy.reduce((suma, w) => suma + (w.stan?.krok ?? 0), 0);
}
const history = {
  _wpisy: [
    { stan: { krok: 1 } },
    { stan: null },
    { stan: { krok: 3 } },
  ],
};
console.log(sumaKrokow(history));
// 4

function czyMoznaCofnac(history) {
  return history._pozycja > 0;
}
console.log(czyMoznaCofnac({ _pozycja: 0 }));
console.log(czyMoznaCofnac({ _pozycja: 2 }));
// false
// true

